#pragma once
namespace kharvox::physicalgk {
// Physical GK disables RS melee at source AND at final native XInput output.
// No ordinary JOY8 punch animation is generated by joystick click when on.
// The only melee pulse left in that mode is from an actual tracked punch.
inline constexpr bool routeStickMelee(bool physicalGK,bool gameplay,bool pressed) noexcept {
    return pressed && !(physicalGK && gameplay);
}
inline constexpr bool routeNativeUse(bool physicalGK,bool gameplay,bool stickUsePulse) noexcept {
    return gameplay && !physicalGK && stickUsePulse;
}
inline constexpr bool routeNativeMelee(bool physicalGK,bool gameplay,
    bool stickDown,bool legacyMeleePulse,bool physicalPunchPulse,
    bool usePhaseExpired) noexcept {
    if(!gameplay)return false;
    if(physicalGK)return physicalPunchPulse;
    return usePhaseExpired && (stickDown || legacyMeleePulse);
}
inline constexpr bool routePhysicalPunch(bool physicalGK,bool gameplay,bool triggered) noexcept {
    return physicalGK && gameplay && triggered;
}
}
